// Directive-free: imported by server pages, metadata and JSON-LD.
// The data is generated by scripts/research/build_landscape.py from the raw,
// sourced vendor research in scripts/research/raw/*.json. Do not edit the JSON by
// hand; fix the raw record (or scripts/research/corrections.json) and rebuild.
import raw from "./voice-landscape.json";
import type { MapPoint } from "@/components/research/charts";

export type CapValue = "yes" | "partial" | "no" | "unknown";
export type CapKey =
  | "hindi_hinglish" | "indic_languages" | "outbound_inbound" | "live_transfer" | "mid_call_actions"
  | "no_code_builder" | "api_webhooks" | "built_in_crm" | "lead_source_connectors" | "whatsapp_followup"
  | "post_call_analysis" | "call_qa" | "human_call_intelligence" | "telephony_included";

type Price = { amount: number | null; currency: string | null; period?: string | null; plan_name?: string | null; notes?: string | null };

export type Vendor = {
  name: string;
  fullName: string;
  region: "india" | "global" | "telleo";
  hq: string | null;
  segment: string;
  website: string;
  target: string | null;
  pricing: {
    public_pricing?: boolean | null;
    entry_price?: Price | null;
    per_minute_from?: Price | null;
    /** What the per-minute price covers (scripts/research/corrections.json). */
    per_minute_scope?: string | null;
    free_trial?: boolean | null;
    price_basis?: string | null;
  };
  capabilities: Record<CapKey, { value: CapValue; evidence: string }>;
  conversation: number;
  workflow: number;
  breadth: number;
  languages: string | null;
  indiaCompliance: string | null;
  scale: { customers_claimed?: string | null; total_funding_usd_m?: number | null; last_round?: string | null };
  ratings: { g2?: { score: number | null; reviews: number | null } | null; capterra?: { score: number | null; reviews: number | null } | null };
  notable: string | null;
  notableSource: string | null;
  sources: Record<string, string>;
  asOf: string;
};

const data = raw as unknown as {
  capLabels: Record<CapKey, string>;
  conversation: CapKey[];
  workflow: CapKey[];
  vendors: Vendor[];
};

export const CAP_LABELS = data.capLabels;
export const CONVERSATION_CAPS = data.conversation;
export const WORKFLOW_CAPS = data.workflow;
export const ALL_CAPS: CapKey[] = [...CONVERSATION_CAPS, ...WORKFLOW_CAPS];
export const VENDORS: Vendor[] = data.vendors;
export const OTHERS: Vendor[] = VENDORS.filter((v) => v.region !== "telleo");
export const TELLEO: Vendor = VENDORS.find((v) => v.region === "telleo")!;

export const LANDSCAPE_SLUG = "voice-ai-platform-landscape-2026";
export const LANDSCAPE_CSV = "/research/voice-ai-platform-landscape-2026.csv";
export const RESEARCH_PUBLISHED = "2026-10-22";
export const RESEARCH_UPDATED = "2026-10-22";

export const SEGMENT_LABELS: Record<string, string> = {
  "voice-agent-platform": "Voice-agent platform",
  "developer-platform": "Developer platform",
  "enterprise-conversational-ai": "Enterprise conversational AI",
  "ccaas-telephony": "Cloud telephony / contact centre",
  "crm-with-ai-calling": "CRM with AI calling",
  "conversation-intelligence": "Conversation intelligence",
};

/** How many of the other vendors document a capability at the given level. */
export function capCount(cap: CapKey, value: CapValue = "yes", pool: Vendor[] = OTHERS) {
  return pool.filter((v) => v.capabilities[cap].value === value).length;
}

/** First source URL we hold for a vendor, preferring capabilities, then pricing. */
export function primarySource(v: Vendor) {
  const s = v.sources;
  const pick = s.capabilities || s.pricing || Object.values(s).find(Boolean) || v.website;
  return pick.split(/\s*;\s*|\s\[/)[0].trim();
}

function money(p: Price) {
  const sym = p.currency === "INR" ? "₹" : p.currency === "USD" ? "$" : p.currency === "EUR" ? "€" : p.currency === "GBP" ? "£" : `${p.currency ?? ""} `;
  return `${sym}${p.amount!.toLocaleString(p.currency === "INR" ? "en-IN" : "en-US", { maximumFractionDigits: 3 })}`;
}

export function formatEntryPrice(v: Vendor) {
  const p = v.pricing;
  const e = p.entry_price;
  if (!e || e.amount == null) return p.public_pricing === false ? "Quote only" : "Not published";
  if (e.amount === 0) return "No monthly fee";
  const per = e.period === "month" ? "/mo" : e.period === "year" ? "/yr" : e.period === "minute" ? "/min" : e.period ? ` /${e.period}` : "";
  return `${money(e)}${per}`;
}

export function formatPerMinute(v: Vendor) {
  const m = v.pricing.per_minute_from;
  return m && m.amount != null ? `${money(m)}/min` : "Not published";
}

/** Group averages for the segment chart. */
export function averageBreadth(filter: (v: Vendor) => boolean) {
  const vs = OTHERS.filter(filter);
  return { n: vs.length, avg: vs.reduce((a, v) => a + v.breadth, 0) / Math.max(1, vs.length) };
}

/* Selective map labels (placed to avoid collisions at the report's width); every
   point keeps its tooltip and its table row. Filled in once the data is in. */
export const MAP_LABELS: Record<string, MapPoint["labelSide"]> = {
  Telleo: "left", "Ringg AI": "right", SquadStack: "left", Vomyra: "right", "Sarvam AI": "right", Vapi: "left",
  Convin: "left", "Yellow.ai": "right", "NiCE Cognigy": "right", Sierra: "left", Gong: "right", Salesken: "above",
  Knowlarity: "right", "Rezo.ai": "right", Haptik: "right", "Observe.AI": "right",
};
export const PHONE_MAP_LABELS: Record<string, MapPoint["labelSide"]> = {
  Telleo: "left", "Ringg AI": "below", Vapi: "left", Gong: "right", "NiCE Cognigy": "right",
};

/** Points for the Voice AI Platform Map. */
export function landscapeMapPoints(labels: Record<string, MapPoint["labelSide"]> = MAP_LABELS): MapPoint[] {
  return VENDORS.map((v) => ({
    label: v.name,
    x: v.conversation,
    y: v.workflow,
    series: v.region,
    detail: `conversation ${v.conversation}%, business workflow ${v.workflow}%, ${v.breadth} of 14 capabilities (${SEGMENT_LABELS[v.segment] ?? v.segment})`,
    showLabel: v.name in labels,
    labelSide: labels[v.name],
  }));
}
